def validate(f):
    from math import atan2, cos, sin, hypot, radians, degrees, sqrt, pi
    from collections import deque
    b=f["board"]; rear=b["rear_support"]; front=b["closed_front"]
    length=hypot(front[0]-rear[0],front[2]-rear[2])
    closed=atan2(front[2]-rear[2],front[0]-rear[0]); lifted=closed+radians(b["lift_angle_degrees"])
    radius=f["cricket"]["radius"]
    def box_d2(p,lo,hi): return sum(max(lo[k]-p[k],0,p[k]-hi[k])**2 for k in range(3))
    def plank_d2(p,origin,angle):
        dx=p[0]-origin[0];dz=p[2]-origin[2]
        q=[dx*cos(angle)+dz*sin(angle),p[1]-origin[1],-dx*sin(angle)+dz*cos(angle)]
        return box_d2(q,[0,-b["width"]/2,-b["thickness"]/2],[length,b["width"]/2,b["thickness"]/2])
    def search(angle):
        lo=f["grid"]["min"]; step=f["grid"]["step"]
        size=[round((f["grid"]["max"][k]-lo[k])/step)+1 for k in range(3)]
        def index(p):return tuple(round((p[k]-lo[k])/step) for k in range(3))
        def point(i):return [round(lo[k]+i[k]*step,8) for k in range(3)]
        def free(i):
            p=point(i)
            return not(any(box_d2(p,w["min"],w["max"])<=radius*radius for w in f["walls"]) or plank_d2(p,rear,angle)<=radius*radius)
        start=index(f["cricket"]["start"]); goal=index(f["cricket"]["safe_goal"])
        if not free(start): return {"start_free":False,"reachable":False,"visited":0,"path":[]}
        todo=deque([start]);seen={start};prev={};found=False
        while todo:
            here=todo.popleft()
            if here==goal:found=True;break
            for axis in range(3):
                for delta in (-1,1):
                    nxt=list(here);nxt[axis]+=delta;nxt=tuple(nxt)
                    if 0<=nxt[axis]<size[axis] and nxt not in seen and free(nxt):
                        seen.add(nxt);prev[nxt]=here;todo.append(nxt)
        path=[]
        if found:
            here=goal
            while here!=start:path.append(point(here));here=prev[here]
            path.append(point(start));path.reverse()
        return {"start_free":True,"reachable":found,"visited":len(seen),"path":path}
    def segment_hits_box(a,z,lo,hi):
        entry=0.;leave=1.
        for k in range(3):
            d=z[k]-a[k]
            if abs(d)<1e-12:
                if a[k]<lo[k] or a[k]>hi[k]:return False
            else:
                t1=(lo[k]-a[k])/d;t2=(hi[k]-a[k])/d
                entry=max(entry,min(t1,t2));leave=min(leave,max(t1,t2))
                if entry>leave:return False
        return True
    closed_search=search(closed);open_search=search(lifted)
    rf=f["reach_fixture"]; x=rf["grip_x"]
    target=[x,rf["grip_y"],rear[2]+(x-rear[0])*sin(closed)/cos(closed)+b["thickness"]/2]
    reach={}
    for who in ("geppetto","pinocchio"):
        start=rf[who+"_shoulder"];reach[who]={"target_distance":sqrt(sum((start[k]-target[k])**2 for k in range(3))),"reach_limit":rf[who+"_reach"],"blocked_by":[w["id"] for w in f["walls"] if segment_hits_box(start,target,w["min"],w["max"])]}
    fall_angles=[pi/2+(closed+pi-pi/2)*n/120 for n in range(121)]
    fall_clearance=min(sqrt(plank_d2(f["cricket"]["start"],front,angle))-radius for angle in fall_angles)
    front_open=[rear[0]+length*cos(lifted),0.,rear[2]+length*sin(lifted)]
    outcomes={
      "closed_fixture_has_no_escape_on_3d_grid":not closed_search["reachable"],
      "lifted_fixture_has_side_escape_on_3d_grid":open_search["reachable"],
      "open_path_does_not_require_jump":bool(open_search["path"]) and max(p[2] for p in open_search["path"])<=f["cricket"]["start"][2]+1e-8,
      "sampled_fall_does_not_hit_static_safe_cricket_proxy":fall_clearance>0,
      "board_fits_between_side_returns":b["width"]<0.60,
      "closed_side_margin_smaller_than_cricket_diameter":(0.60-b["width"])/2<2*radius,
      "adult_current_hand_ray_is_occluded_despite_sufficient_length":bool(reach["geppetto"]["blocked_by"]) and reach["geppetto"]["target_distance"]<reach["geppetto"]["reach_limit"],
      "child_current_hand_ray_is_clear_and_within_length":not reach["pinocchio"]["blocked_by"] and reach["pinocchio"]["target_distance"]<reach["pinocchio"]["reach_limit"]
    }
    return {"scope":"ABSTRACT_FIXTURE_ONLY_NOT_VIDEO_OR_APPROVED_LAYOUT_PASS","checks":outcomes,"passed":sum(outcomes.values()),"total":len(outcomes),"closed_angle_degrees":degrees(closed),"lifted_angle_degrees":degrees(lifted),"board_length":length,"open_front":front_open,"closed_search":closed_search,"open_search":open_search,"reach":reach,"grip_proxy":target,"sampled_fall_min_proxy_clearance":fall_clearance,"fall_sample_count":len(fall_angles),"limits":["Finite-grid path finding is an illustrative discrete test, not proof for arbitrary character anatomy or all continuous trajectories.","The geometric proxy says nothing about actual character jump ability; blocked jumping follows the fixture enclosure rather than a new no-jump character rule.","Body reach, gravity, mass, friction, structural stability, finger grip, foot contact, and board restoration are not physically simulated.","Approved background, sprite/rig proportions and real camera must be measured before using this layout.","A current-pose occluded hand ray is not permanent adult incapacity; Geppetto can change position after the child's safe opening action."]}
